#include <DHT.h>

#define DHT_PIN 2 // Pin connected to DHT22 sensor

DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
}

void loop() {
  // Take multiple readings
  float tempReadings[10], humReadings[10];
  for (int i = 0; i < 10; i++) {
    dht.read();
    tempReadings[i] = dht.temperature;
    humReadings[i] = dht.humidity;
    delay(1000); // wait 1 second between readings
  }

  // Calculate average temperature and humidity readings
  float avgTemp = 0, avgHum = 0;
  for (int i = 0; i < 10; i++) {
    avgTemp += tempReadings[i];
    avgHum += humReadings[i];
  }
  avgTemp /= 10;
  avgHum /= 10;

  // Calculate correction factors
  float tempCorrectionFactor = 0, humCorrectionFactor = 0;
  if (avgTemp != 0) {
    tempCorrectionFactor = (referenceTemperature - avgTemp) / avgTemp;
  }
  if (avgHum != 0) {
    humCorrectionFactor = (referenceHumidity - avgHum) / avgHum;
  }

  // Print correction factors
  Serial.print("Temperature Correction Factor: ");
  Serial.print(tempCorrectionFactor);
  Serial.println();
  Serial.print("Humidity Correction Factor: ");
  Serial.print(humCorrectionFactor);
  Serial.println();

  // Apply correction factors to subsequent readings
  void readAndPrintReading() {
    dht.read();
    float temp = dht.temperature * (1 + tempCorrectionFactor);
    float hum = dht.humidity * (1 + humCorrectionFactor);
    Serial.print("Temperature: ");
    Serial.print(temp);
    Serial.println(" C");
    Serial.print("Humidity: ");
    Serial.print(hum);
    Serial.println(" %");
    delay(1000);
  }

  while (true) {
    readAndPrintReading();
  }
}
